659	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
660	    let data = fs::read(path)
661	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
662	    let records = split_records(&data);
663	    let size = records.len() as u64;
664	    if index >= size {
665	        return Err(ProveError::Missing(index, size));
666	    }
667	    let idx = index as usize;
668	    let (root, audit_path) = root_and_path(&records, idx);
669	    Ok(proof_json(size, index, &root, &audit_path))
670	}
