726	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data).
727	fn leaf_hash(data: &[u8]) -> [u8; 32] {
728	    let mut input = Vec::with_capacity(1 + data.len());
729	    input.push(0x00);
730	    input.extend_from_slice(data);
731	    sha256(&input)
732	}
733	
734	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
735	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
736	    let mut input = Vec::with_capacity(65);
737	    input.push(0x01);
738	    input.extend_from_slice(left);
739	    input.extend_from_slice(right);
740	    sha256(&input)
741	}
742	
743	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256.
744	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
745	    match leaves.len() {
746	        0 => sha256(&[]),
747	        1 => leaf_hash(leaves[0]),
748	        n => {
749	            // Largest power of two strictly smaller than n.
750	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
751	            node_hash(&mth(&leaves[..k]), &mth(&leaves[k..]))
752	        }
753	    }
754	}
