802	fn hex(digest: &[u8; 32]) -> String {
803	    let mut s = String::with_capacity(64);
804	    for b in digest {
805	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
806	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
807	    }
808	    s
809	}
