306	#[test]
307	fn record_file_is_used_verbatim_without_lf_splitting_or_trimming() {
308	    let empty_pos2 = proof_for_index(2, ROOT_B9);
309	    // Zero-byte record file is the empty record and verifies.
310	    assert_verified("zero-byte file", b"", &empty_pos2, "9", ROOT_B9);
311	    // Any added byte changes the record: terminating LF explicitly, plus a
312	    // space and CR (all preserved), all fail.
313	    assert_verification_failed("empty + LF", b"\n", &empty_pos2, "9", ROOT_B9);
314	    assert_verification_failed("empty + space", b" ", &empty_pos2, "9", ROOT_B9);
315	    assert_verification_failed("empty + CR", b"\r", &empty_pos2, "9", ROOT_B9);
316	    assert_verification_failed("empty + NUL", b"\x00", &empty_pos2, "9", ROOT_B9);
317	
318	    // A normal record with an extra terminating LF must fail.
319	    assert_verification_failed(
320	        "alpha + trailing LF",
321	        b"alpha\n",
322	        proof_json(9, 0, ROOT_B9, PATH_B9_M0).as_bytes(),
323	        "9",
324	        ROOT_B9,
325	    );
326	    // Internal LF is just a byte in the record file, not a separator.
327	    assert_verification_failed(
328	        "alpha LF beta is one record file",
329	        b"alpha\nbeta",
330	        proof_json(9, 0, ROOT_B9, PATH_B9_M0).as_bytes(),
331	        "9",
332	        ROOT_B9,
333	    );
334	
335	    // Binary record through real prove interop: NUL/non-UTF-8/CR preserved.
336	    let batch = TempFile::create(PAYLOAD_B9);
337	    let proved = Command::new(common::bin())
338	        .arg("prove")
339	        .arg(&batch.path)
340	        .arg("6")
341	        .output()
342	        .unwrap();
343	    let proof_file = TempFile::create(&proved.stdout);
344	    let good = TempFile::create(b"\xff\xfe\x00binary");
345	    let out = run(&good.path, &proof_file.path, "9", ROOT_B9);
346	    assert_eq!(out.status.code(), Some(0), "{}", String::from_utf8_lossy(&out.stderr));
347	    let bad = TempFile::create(b"\xff\xfe\x00binarX");
348	    let out = run(&bad.path, &proof_file.path, "9", ROOT_B9);
349	    assert_eq!(out.status.code(), Some(1));
350	    assert!(out.stdout.is_empty());
351	}
