353	// --- Trusted size/root must come from the command line -----------------------
354	
355	#[test]
356	fn proof_fields_cannot_substitute_for_trusted_values() {
357	    let proof = proof_json(9, 4, ROOT_B9, PATH_B9_M4);
358	
359	    // Trusted size different from the proof's tree_size: fail even though the
360	    // proof itself is internally consistent.
361	    assert_verification_failed("trusted size 8 vs proof 9", b"alpha", proof.as_bytes(), "8", ROOT_B9);
362	    assert_verification_failed("trusted size 10 vs proof 9", b"alpha", proof.as_bytes(), "10", ROOT_B9);
363	
364	    // Trusted root different from the proof's embedded root.
365	    let mut wrong = String::from(ROOT_B9);
366	    wrong.replace_range(63..64, if &ROOT_B9[63..64] == "0" { "1" } else { "0" });
367	    assert_verification_failed("wrong trusted root", b"alpha", proof.as_bytes(), "9", &wrong);
368	
369	    // A proof embedding a different root must not verify against the trusted
370	    // B9 root even with matching tree_size/index/path geometry for B9.
371	    assert_verification_failed(
372	        "proof root ROOT_B8 cannot pose as B9",
373	        b"alpha",
374	        proof_json(9, 4, ROOT_B8, PATH_B9_M4).as_bytes(),
375	        "9",
376	        ROOT_B9,
377	    );
378	}
