417	#[test]
418	fn missing_or_extra_audit_hashes_fail_including_single_record_tree() {
419	    // Remove one hash from the four required by B9 m=4.
420	    let short: Vec<&str> = PATH_B9_M4[..3].to_vec();
421	    assert_verification_failed(
422	        "path one hash short",
423	        b"alpha",
