506	        format!("{{\"tree_size\":9e0,\"leaf_index\":4,\"root\":\"{h}\",\"audit_path\":[]}}").into_bytes(),
507	        format!("{{\"tree_size\":18446744073709551616,\"leaf_index\":4,\"root\":\"{h}\",\"audit_path\":[]}}").into_bytes(),
508	        format!("{{\"tree_size\":1e400,\"leaf_index\":4,\"root\":\"{h}\",\"audit_path\":[]}}").into_bytes(),
509	        // Hash strings in the wrong shape/case.
510	        format!("{{\"tree_size\":9,\"leaf_index\":4,\"root\":\"{}\",\"audit_path\":[]}}", h.to_uppercase()).into_bytes(),
511	        format!("{{\"tree_size\":9,\"leaf_index\":4,\"root\":\"{h}00\",\"audit_path\":[]}}").into_bytes(),
